package io.github.classgraph;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

import nonapi.io.github.classgraph.concurrency.AutoCloseableExecutorService;
import nonapi.io.github.classgraph.json.JSONDeserializer;
import nonapi.io.github.classgraph.json.JSONSerializer;
import nonapi.io.github.classgraph.scanspec.ScanSpec;
import nonapi.io.github.classgraph.utils.Assert;
import nonapi.io.github.classgraph.utils.CollectionUtils;

/** Serialization and deserialization support for {@link ScanResult}. */
public final class ScanResultSerialization {
    private static final String CURRENT_SERIALIZATION_FORMAT = "10";

    private ScanResultSerialization() {
    }

    /** Serialize a scan result to JSON. */
    public static String toJSON(final ScanResult scanResult, final int indentWidth) {
        Assert.notNull(scanResult, "scanResult");
        final List<ClassInfo> allClassInfo = new ArrayList<>(scanResult.classNameToClassInfo.values());
        CollectionUtils.sortIfNotEmpty(allClassInfo);
        final List<PackageInfo> allPackageInfo = new ArrayList<>(getMap(scanResult, "packageNameToPackageInfo").values());
        CollectionUtils.sortIfNotEmpty(allPackageInfo);
        final List<ModuleInfo> allModuleInfo = new ArrayList<>(getMap(scanResult, "moduleNameToModuleInfo").values());
        CollectionUtils.sortIfNotEmpty(allModuleInfo);
        return JSONSerializer.serializeObject(new SerializationFormat(CURRENT_SERIALIZATION_FORMAT, scanResult.scanSpec,
                allClassInfo, allPackageInfo, allModuleInfo, getField(scanResult, "rawClasspathEltOrderStrs")),
                indentWidth, false);
    }

    /** Deserialize a scan result from JSON. */
    public static ScanResult fromJSON(final String json) {
        Assert.notNull(json, "json");
        final var matcher = Pattern.compile("\\{[\\n\\r ]*\\\"format\\\"[ ]?:[ ]?\\\"([^\\\"]+)\\\"").matcher(json);
        if (!matcher.find()) {
            throw new IllegalArgumentException("JSON is not in correct format");
        }
        if (!CURRENT_SERIALIZATION_FORMAT.equals(matcher.group(1))) {
            throw new IllegalArgumentException(
                    "JSON was serialized in a different format from the format used by the current version of "
                            + "ClassGraph -- please serialize and deserialize your ScanResult using the same version of ClassGraph");
        }

        final var deserialized = JSONDeserializer.deserializeObject(SerializationFormat.class, json);
        if (deserialized == null || !CURRENT_SERIALIZATION_FORMAT.equals(deserialized.format)) {
            throw new IllegalArgumentException("JSON was serialized by newer version of ClassGraph");
        }

        final var classGraph = new ClassGraph();
        classGraph.scanSpec = deserialized.scanSpec;
        final ScanResult scanResult;
        try (var executorService = new AutoCloseableExecutorService(ClassGraph.DEFAULT_NUM_WORKER_THREADS)) {
            scanResult = classGraph.getClasspathScanResult(executorService);
        }

        setField(scanResult, "rawClasspathEltOrderStrs", deserialized.classpath);
        scanResult.scanSpec = deserialized.scanSpec;
        scanResult.classNameToClassInfo = new HashMap<>();
        if (deserialized.classInfo != null) {
            for (final ClassInfo classInfo : deserialized.classInfo) {
                scanResult.classNameToClassInfo.put(classInfo.getName(), classInfo);
                classInfo.setScanResult(scanResult);
            }
        }

        final Map<String, ModuleInfo> moduleInfo = new HashMap<>();
        if (deserialized.moduleInfo != null) {
            for (final ModuleInfo info : deserialized.moduleInfo) {
                moduleInfo.put(info.getName(), info);
            }
        }
        setField(scanResult, "moduleNameToModuleInfo", moduleInfo);

        final Map<String, PackageInfo> packageInfo = new HashMap<>();
        if (deserialized.packageInfo != null) {
            for (final PackageInfo info : deserialized.packageInfo) {
                packageInfo.put(info.getName(), info);
            }
        }
        setField(scanResult, "packageNameToPackageInfo", packageInfo);

        try {
            final Method index = ScanResult.class.getDeclaredMethod("indexResourcesAndClassInfo", nonapi.io.github.classgraph.utils.LogNode.class);
            index.setAccessible(true);
            index.invoke(scanResult, new Object[] { null });
            setField(scanResult, "isObtainedFromDeserialization", true);
        } catch (final ReflectiveOperationException e) {
            throw new IllegalStateException("Could not initialize deserialized ScanResult", e);
        }
        return scanResult;
    }

    @SuppressWarnings("unchecked")
    private static <K, V> Map<K, V> getMap(final ScanResult scanResult, final String name) {
        return (Map<K, V>) getField(scanResult, name);
    }

    @SuppressWarnings("unchecked")
    private static <T> T getField(final ScanResult scanResult, final String name) {
        try {
            final Field field = ScanResult.class.getDeclaredField(name);
            field.setAccessible(true);
            return (T) field.get(scanResult);
        } catch (final ReflectiveOperationException e) {
            throw new IllegalStateException("Could not read ScanResult field " + name, e);
        }
    }

    private static void setField(final ScanResult scanResult, final String name, final Object value) {
        try {
            final Field field = ScanResult.class.getDeclaredField(name);
            field.setAccessible(true);
            field.set(scanResult, value);
        } catch (final ReflectiveOperationException e) {
            throw new IllegalStateException("Could not write ScanResult field " + name, e);
        }
    }

    private static final class SerializationFormat {
        public String format;
        public ScanSpec scanSpec;
        public List<String> classpath;
        public List<ClassInfo> classInfo;
        public List<PackageInfo> packageInfo;
        public List<ModuleInfo> moduleInfo;

        @SuppressWarnings({ "unused", "NullAway.Init" })
        public SerializationFormat() {
        }

        SerializationFormat(final String format, final ScanSpec scanSpec, final List<ClassInfo> classInfo,
                final List<PackageInfo> packageInfo, final List<ModuleInfo> moduleInfo, final List<String> classpath) {
            this.format = format;
            this.scanSpec = scanSpec;
            this.classpath = classpath;
            this.classInfo = classInfo;
            this.packageInfo = packageInfo;
            this.moduleInfo = moduleInfo;
        }
    }
}
